#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# W1: symbol-scaling measurement for mql5/Experts/TickStreamer/TickStreamer.mq5
# (ADR-0004). All instructional text is Japanese; the shared library above the
# marker keeps its original English chrome (it must not be hand-edited).
#
# Two modes, selected with --mode:
#   baseline (default)  measures the E0 build -- the EA source pinned at
#                        commit 760f2c3, which still has InpTimerMs and
#                        InpMeasureTickLoss and the two-run (loss=off/on)
#                        methodology. This wizard compiles that commit's
#                        source from a temp copy; the operator never has to
#                        check out an old commit by hand.
#   after                measures HEAD -- post-E1 (structural refactor),
#                        post-E2 (extra symbols stream every tick via
#                        CopyTicks; InpPollMs replaces InpTimerMs;
#                        InpMeasureTickLoss is gone) and post-E3
#                        (InpExtraMode=EXTRA_EVENT: a TickSpy indicator per
#                        extra symbol wakes the EA instead of the timer
#                        alone). Stage 1 also compiles and installs
#                        TickSpy.ex5. Stage 4 is a live behaviour checkpoint
#                        for E1/E2/E3 before the sweep runs each N twice --
#                        EXTRA_POLL then EXTRA_EVENT, same InpSymbols (no
#                        loss=on run -- that flag no longer exists) -- plus
#                        an offline ground-truth stage for N=10 (POLL
#                        required, EVENT optional).
#
# Usage:
#   benchmarks/wizard_baseline_sweep.sh                              # baseline, from stage 1
#   benchmarks/wizard_baseline_sweep.sh --mode after                 # after, from stage 1
#   benchmarks/wizard_baseline_sweep.sh --mode after --from-step 6   # resume after at N=10
#   benchmarks/wizard_baseline_sweep.sh --help

# -- arg parsing --------------------------------------------------------
MODE="baseline"
FROM_STEP=1
HELP=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    --help|-h)
      HELP=1
      shift
      ;;
    --mode)
      MODE="${2:-baseline}"
      shift 2
      ;;
    --from-step)
      FROM_STEP="${2:-1}"
      shift 2
      ;;
    *)
      shift
      ;;
  esac
done

case "$MODE" in
  baseline|after) ;;
  *)
    printf 'unknown --mode: %s (must be baseline or after)\n' "$MODE" >&2
    exit 1
    ;;
esac

if [[ "$HELP" -eq 1 ]]; then
  cat <<'EOF'
使い方: wizard_baseline_sweep.sh [--mode baseline|after] [--from-step N]

--mode baseline（既定）: E0（コミット 760f2c3）の EA を基準に計測します。
  1  事前準備（760f2c3 の EA を一時コピーからコンパイル・配置・再読込確認）
  2  ブリッジ起動
  3  Market Watch シンボルリストの取得
  4  N=1（チャートのみ）計測（InpMeasureTickLoss を loss=off→on の2回で計測）
  5  N=10 計測
  6  N=50 計測
  7  N=all（*）計測
  8  まとめ

--mode after: HEAD（E1構造リファクタ + E2 全ティック配信 + E3 EXTRA_EVENT配信）の EA を検証・計測します。
  1  事前準備（HEAD の EA を、EXTRA_EVENT 用の TickSpy インジケータとあわせてコンパイル・配置・再読込確認）
  2  ブリッジ起動
  3  Market Watch シンボルリストの取得
  4  動作チェックポイント（接続/再接続ウォッチドッグ/ウォームアップ/ct_err/timer= ログに加え、
     EXTRA_EVENT へ切り替えて mode=event / evt_n>0 / evt_bad=0 / evt_late比を確認し、
     各項目の pass/fail を結果ファイルに記録。N=all・EVENT でのメモリ/CPUはStage 8で追記）
  5  N=1（チャートのみ）計測（EXTRA_POLL→EXTRA_EVENT の順に2回）
  6  N=10 計測（同上、2回）
  7  N=50 計測（同上、2回）
  8  N=all（*）計測（同上、2回。EVENT側の直後にメモリ/CPUを記録）
  9  オフライン ground truth（N=10 の受信窓を計測し、CountTicks.mq5 で端末側を数え、
     compare_tick_counts.py で突き合わせて ticks lost を算出。EXTRA_POLL は必須、
     EXTRA_EVENT は任意で同じ手順をもう一度実行可能）
  10 まとめ（Nごとに POLL/EVENT の統計行を並べて表示。どちらが勝ったかは
     hop p50/p99 を見て操作者が判断します）

途中で Ctrl-C しても、次回 --mode <baseline|after> --from-step N で該当ステージから再開できます
（それより前のステージで確定した値は、モードごとに分かれた保存済みの状態を使います）。
EOF
  exit 0
fi

# -- paths ---------------------------------------------------------------
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RESULTS_DIR="$REPO_ROOT/benchmarks/results"
mkdir -p "$RESULTS_DIR"

# This wizard has no secrets — it persists measurement/setup state instead of
# .env values, but reuses the same ask()/write_env() machinery (idempotent
# defaults, "[Enter keeps current]") for that purpose. State is kept separate
# per --mode so a baseline run and an after run never clobber each other's
# --from-step resume point.
ENV_FILE="$RESULTS_DIR/.wizard_state.${MODE}"

# -- path conversion (Git Bash <-> native Windows paths) -----------------
to_unix_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -u "$1"
  else printf '%s' "$1" | sed -E 's#^([A-Za-z]):#/\L\1#' | sed 's#\\#/#g'
  fi
}
to_win_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"
  else printf '%s' "$1" | sed -E 's#^/([A-Za-z])/#\U\1:/#'
  fi
}

WIN_REPO_ROOT="$(to_win_path "$REPO_ROOT")"

# -- state load (so a run resumed with --from-step still has earlier values)
load_state() {
  [[ -f "$ENV_FILE" ]] || return 0
  local line key value
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ "$line" == *=* ]] || continue
    key="${line%%=*}"
    value="${line#*=}"
    printf -v "$key" '%s' "$value"
  done < "$ENV_FILE"
}
load_state

RUN_DATE="${RUN_DATE:-$(date +%Y%m%d)}"
write_env RUN_DATE "$RUN_DATE" >/dev/null
RESULTS_MD="$RESULTS_DIR/${MODE}-${RUN_DATE}.md"

if [[ ! -f "$RESULTS_MD" ]]; then
  if [[ "$MODE" == "baseline" ]]; then
    {
      printf '# ベースライン symbol-scaling 計測 -- %s\n\n' "$RUN_DATE"
      printf '生成: %s (wizard: benchmarks/wizard_baseline_sweep.sh --mode baseline)\n\n' "$(date '+%Y-%m-%d %H:%M:%S')"
      printf 'これは E0（コミット 760f2c3）時点の EA を計測した before の値です。'
      printf 'ADR-0004 / docs/latency.md の Symbol scaling table 更新に使います。\n'
      printf '\n注意: baseline と after は同じ市場セッション内で交互に計測してください'
      printf '（時間帯が離れるとティックレートの違いが測定対象の差を飲み込みます -- docs/latency.md）。\n'
    } > "$RESULTS_MD"
  else
    {
      printf '# after（E1+E2）symbol-scaling 計測 -- %s\n\n' "$RUN_DATE"
      printf '生成: %s (wizard: benchmarks/wizard_baseline_sweep.sh --mode after)\n\n' "$(date '+%Y-%m-%d %H:%M:%S')"
      printf 'これは HEAD（E1 構造リファクタ + E2 全ティック配信）時点の EA を計測した after の値です。'
      printf 'ADR-0004 / docs/latency.md の Symbol scaling table 更新に使います。\n'
      printf '\n注意: baseline と after は同じ市場セッション内で交互に計測してください'
      printf '（時間帯が離れるとティックレートの違いが測定対象の差を飲み込みます -- docs/latency.md）。\n'
    } > "$RESULTS_MD"
  fi
fi

# -- stage gating: resume support without touching stage()'s own counter --
run_stage() {
  local idx="$1" title="$2"
  if (( idx < FROM_STEP )); then return 1; fi
  _STAGE_INDEX=$((idx - 1))
  stage "$title"
  return 0
}

# -- small helpers authored for this wizard -------------------------------

# port_busy PORT — true if something is already listening on 127.0.0.1:PORT.
port_busy() {
  (exec 3<>"/dev/tcp/127.0.0.1/$1") 2>/dev/null
}

# run_ps1 SCRIPT — write SCRIPT to a temp .ps1 and run it, streaming stdout.
run_ps1() {
  local script="$1" tmp win_tmp
  tmp="$(mktemp --suffix=.ps1)"
  printf '%s\n' "$script" > "$tmp"
  win_tmp="$(to_win_path "$tmp")"
  powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File "$win_tmp"
  local rc=$?
  rm -f "$tmp"
  return $rc
}

# append_result "見出し" "本文" — append one block to $RESULTS_MD.
append_result() {
  { printf '\n%s\n\n' "$1"; printf '%s\n' "$2"; } >> "$RESULTS_MD"
  printf '  %s✓ 追記%s -> %s\n' "$GREEN" "$RESET" "$RESULTS_MD"
}

# normalize_symbols BLOB — split on comma/tab/space across every line, trim,
# dedupe (order preserved), re-join as one comma list.
normalize_symbols() {
  awk -F'[,\t ]+' '
    { for (i=1;i<=NF;i++) {
        s=$i; gsub(/^[ \t\r]+|[ \t\r]+$/,"",s)
        if (s!="" && !seen[s]++) out = out (out=="" ? "" : ",") s
      } }
    END{ print out }' <<<"$1"
}

# extract_symbols_from_paste RAW — keep only the first tab-separated field of
# each line (Market Watch's multi-select copy is "Symbol<TAB>Bid<TAB>Ask...").
extract_symbols_from_paste() {
  local line
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    printf '%s\n' "${line%%$'\t'*}"
  done <<<"$1"
}

# first_n_symbols N LIST — first N symbols of a normalized comma list.
first_n_symbols() {
  local n="$1" list="$2"
  printf '%s' "$list" | tr ',' '\n' | head -n "$n" \
    | awk '{out=out (out==""?"":",") $0} END{print out}'
}

# ask_multiline KEY "prompt" — like ask(), but reads lines until a blank line
# (so a Market Watch multi-row paste, or a multi-line log excerpt, can be
# captured), joining with newlines.
ask_multiline() {
  local key="$1" prompt="$2" current line buf=""
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[空行のままEnterで既存値を使用]%s\n' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s\n' "$BOLD" "$prompt" "$RESET"
  fi
  while IFS= read -r line; do
    [[ -z "$line" ]] && break
    buf+="${line}"$'\n'
  done
  if [[ -z "$buf" && -n "$current" ]]; then buf="$current"; fi
  printf -v "$key" '%s' "$buf"
}

# start_bridge_window — (re)launch the bridge in its own console window,
# writing a small .cmd so the window survives after this script's own process
# tree. Shared by Stage 2 and by the after-mode checkpoint's restart step.
start_bridge_window() {
  local bridge_cmd_win bridge_cmd_unix
  bridge_cmd_win="${WIN_REPO_ROOT}\\benchmarks\\results\\start_bridge.cmd"
  bridge_cmd_unix="$(to_unix_path "$bridge_cmd_win")"
  {
    printf '@echo off\r\n'
    printf 'cd /d "%s"\r\n' "$WIN_REPO_ROOT"
    printf 'echo mt5-ws-stream bridge (tcp:9800  ws/http:8765) -- このウィンドウは開いたままにしてください\r\n'
    printf 'python -m mt5_ws_stream bridge\r\n'
    printf 'echo.\r\n'
    printf 'echo bridge stopped -- press any key to close\r\n'
    printf 'pause >nul\r\n'
  } > "$bridge_cmd_unix"

  if command -v cmd.exe >/dev/null 2>&1; then
    cmd.exe //c start "" "$bridge_cmd_win" >/dev/null 2>&1 \
      && say "新しいウィンドウでブリッジを起動しました。" \
      || warn "自動起動に失敗しました。手動で次を実行してください: $bridge_cmd_win"
  else
    warn "cmd.exe が見つかりません。手動で次を実行してください: python -m mt5_ws_stream bridge"
  fi
  note "自動起動できない場合は、別のターミナルを開いて次を実行してください:"
  note "  cd \"$WIN_REPO_ROOT\" && python -m mt5_ws_stream bridge"
}

# compile_and_install SRC_MQ5_WIN SRC_EX5_WIN INSTALL_PATH_WIN LABEL — compile
# SRC_MQ5_WIN with MetaEditor (requires $METAEDITOR_PATH already set), then
# copy the resulting .ex5 to INSTALL_PATH_WIN, backing up any existing file
# there first. Mirrors Stage 1's EA compile/install ceremony (compile log,
# UTF-16LE→UTF-8 conversion, "Result: 0 errors" check, timestamped backup) so
# Stage 9 can install a second artifact (CountTicks.ex5) the same way without
# duplicating that ceremony inline.
compile_and_install() {
  local src_mq5_win="$1" src_ex5_win="$2" install_path="$3" label="$4"

  local compile_log_win compile_log_unix
  compile_log_win="${WIN_REPO_ROOT}\\benchmarks\\results\\compile-${label}.log"
  compile_log_unix="$(to_unix_path "$compile_log_win")"

  say "MetaEditor で ${label} をコンパイルします（GUIは出ません。数秒かかります）..."
  run_ps1 "
    \$src = '${src_mq5_win}'
    \$log = '${compile_log_win}'
    \$exe = '${METAEDITOR_PATH}'
    Start-Process -FilePath \$exe -ArgumentList \"/compile:\`\"\$src\`\"\", \"/log:\`\"\$log\`\"\" -Wait -WindowStyle Hidden
  " >/dev/null

  local compile_log_utf8
  compile_log_utf8="$(mktemp)"
  if [[ -f "$compile_log_unix" ]]; then
    iconv -f UTF-16LE -t UTF-8 "$compile_log_unix" 2>/dev/null | tr -d '\r' > "$compile_log_utf8" \
      || cp "$compile_log_unix" "$compile_log_utf8"
    say "コンパイルログ（末尾）:"
    tail -n 8 "$compile_log_utf8" | sed 's/^/    /'
  else
    warn "ログファイルが生成されませんでした: $compile_log_win"
  fi

  if ! grep -q "^Result: 0 errors" "$compile_log_utf8" 2>/dev/null; then
    warn "コンパイルエラーが発生した可能性があります（上のログを確認してください）。"
    confirm "それでも続行しますか？（推奨しません）" \
      || { warn "ソースを修正してから再実行してください。"; rm -f "$compile_log_utf8"; exit 1; }
  else
    say "コンパイル成功（0 errors）。"
  fi
  rm -f "$compile_log_utf8"

  local src_ex5_unix
  src_ex5_unix="$(to_unix_path "$src_ex5_win")"
  if [[ ! -f "$src_ex5_unix" ]]; then
    warn "コンパイル済み .ex5 が見つかりません: $src_ex5_win"
    exit 1
  fi

  local install_unix
  install_unix="$(to_unix_path "$install_path")"
  if [[ -f "$install_unix" ]]; then
    local backup_path
    backup_path="${install_path}.bak-$(date +%Y%m%d-%H%M%S)"
    say "既存の .ex5 が見つかりました。バックアップしてから上書きします:"
    say "  上書き対象: $install_path"
    say "  バックアップ先: $backup_path"
    confirm "上書きしてよいですか？" \
      || { warn "中断しました。"; exit 1; }
    cp "$install_unix" "$(to_unix_path "$backup_path")"
    say "バックアップ完了。"
  fi
  mkdir -p "$(dirname "$install_unix")"
  cp "$src_ex5_unix" "$install_unix"
  say "配置完了: $install_path"
}

# record_check ID "question" — a checkpoint confirm that never aborts the
# wizard: it records PASS/FAIL to $RESULTS_MD and bumps CHECK_FAIL_COUNT on a
# fail, so Stage 4 (after mode) can show every check's result before the
# operator decides whether to proceed. Contrast with confirm(), which is a
# hard gate used everywhere else.
CHECK_FAIL_COUNT=0
record_check() {
  local id="$1" question="$2"
  if confirm "$question"; then
    append_result "### チェック ${id}" "結果: PASS"
  else
    CHECK_FAIL_COUNT=$((CHECK_FAIL_COUNT + 1))
    append_result "### チェック ${id}" "結果: FAIL"
    warn "チェック ${id} を FAIL として記録しました。"
  fi
}

# ──────────────────────────────────────────────────────────────────────────
if [[ "$MODE" == "baseline" ]]; then
  TOTAL_STAGES=8
  banner "TickStreamer ベースライン symbol-scaling 計測（baseline / E0=760f2c3）"
else
  TOTAL_STAGES=10
  banner "TickStreamer after symbol-scaling 計測（after / HEAD, E1+E2チェックポイント）"
fi

# ============================================================================
# Stage 1 -- 事前準備: コンパイル・配置・EA再読込
# ============================================================================
if run_stage 1 "事前準備 -- EAのコンパイルと配置"; then
  if [[ "$MODE" == "baseline" ]]; then
    say "コミット 760f2c3（E0: リファクタ前・extra symbols は poll ごとに最新1本だけ配信していた頃）の"
    say "TickStreamer.mq5 を一時コピーとして書き出し、それをコンパイル・配置します。"
    note "このソースには InpTimerMs（poll間隔、既定1ms）と InpMeasureTickLoss（診断モード）があります。"
    note "現在の HEAD には両方とも存在しません（InpTimerMs は InpPollMs に改名・既定10ms、"
    note "InpMeasureTickLoss は削除され、CopyTicks の統計が常時出力されるようになりました）。"

    BASELINE_SRC_DIR="$RESULTS_DIR/ea-baseline"
    mkdir -p "$BASELINE_SRC_DIR"
    BASELINE_SRC_MQ5_UNIX="$BASELINE_SRC_DIR/TickStreamer.mq5"
    say "760f2c3 の TickStreamer.mq5 を書き出しています: $BASELINE_SRC_MQ5_UNIX"
    if ! ( cd "$REPO_ROOT" && git show 760f2c3:mql5/Experts/TickStreamer/TickStreamer.mq5 > "$BASELINE_SRC_MQ5_UNIX" ); then
      warn "760f2c3 のソース書き出しに失敗しました。git のワークツリー/コミットハッシュを確認してください。"
      exit 1
    fi
    SRC_MQ5_UNIX="$BASELINE_SRC_MQ5_UNIX"
    SRC_MQ5_WIN="${WIN_REPO_ROOT}\\benchmarks\\results\\ea-baseline\\TickStreamer.mq5"
    SRC_EX5_WIN="${WIN_REPO_ROOT}\\benchmarks\\results\\ea-baseline\\TickStreamer.ex5"
  else
    say "HEAD（post-E1 構造リファクタ + post-E2 全ティック配信）の TickStreamer.mq5 をコンパイル・配置します。"
    say "対象ソース: mql5/Experts/TickStreamer/TickStreamer.mq5"
    note "統計行に extra_obs=/extra_sent=/ct_n=/ct_us_avg=/ct_us_max=/ct_err= が常時出ます"
    note "（InpMeasureTickLoss は存在しません）。InpPollMs（既定10ms）が InpTimerMs の後継です。"
    SRC_MQ5_UNIX="$REPO_ROOT/mql5/Experts/TickStreamer/TickStreamer.mq5"
    SRC_MQ5_WIN="${WIN_REPO_ROOT}\\mql5\\Experts\\TickStreamer\\TickStreamer.mq5"
    SRC_EX5_WIN="${WIN_REPO_ROOT}\\mql5\\Experts\\TickStreamer\\TickStreamer.ex5"
  fi

  if port_busy 9800 || port_busy 8765; then
    warn "ポート 9800（feeder）または 8765（ws/http）が既に使用中です。"
    say "既にブリッジが動いている可能性があります。計測を始める前に一度停止してください"
    say "（そのウィンドウで Ctrl-C）。ブリッジは Stage 2 で改めて起動します。"
    confirm "このまま続行しますか？（ブリッジは動いていない、または問題ないことを確認済み）" \
      || { warn "中断しました。ブリッジを止めてから --from-step 1 で再開してください。"; exit 1; }
  fi

  METAEDITOR_PATH="${METAEDITOR_PATH:-C:\Program Files\MetaTrader 5\MetaEditor64.exe}"
  if [[ ! -f "$(to_unix_path "$METAEDITOR_PATH")" ]]; then
    warn "既定の場所に MetaEditor64.exe が見つかりません: $METAEDITOR_PATH"
    ask METAEDITOR_PATH "MetaEditor64.exe のフルパスを入力してください:"
  fi
  write_env METAEDITOR_PATH "$METAEDITOR_PATH"

  # ターミナルのデータフォルダを自動検出する（MQL5\Experts に TickStreamer.ex5
  # を持つものを探す。見つからなければ MQL5\Experts があるフォルダを候補として
  # 列挙し、ユーザーに選んでもらう）。
  if [[ -z "${TERMINAL_DIR:-}" ]]; then
    say "MetaTrader のターミナルデータフォルダを検索しています..."
    HITS="$(run_ps1 '
      $root = Join-Path $env:APPDATA "MetaQuotes\Terminal"
      if (Test-Path $root) {
        Get-ChildItem -Path $root -Directory -ErrorAction SilentlyContinue | ForEach-Object {
          $experts = Join-Path $_.FullName "MQL5\Experts"
          if (Test-Path $experts) {
            $hit = Get-ChildItem -Path $experts -Recurse -Filter "TickStreamer.ex5" -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($hit) { Write-Output "$($_.FullName)|$($hit.FullName)" }
            else { Write-Output "$($_.FullName)|" }
          }
        }
      }
    ' | tr -d '\r')"
    WITH_EX5="$(printf '%s\n' "$HITS" | awk -F'|' '$2!="" {print}')"
    N_WITH_EX5=$(printf '%s\n' "$WITH_EX5" | grep -c '.' || true)

    if [[ "$N_WITH_EX5" -eq 1 ]]; then
      TERMINAL_DIR="$(printf '%s\n' "$WITH_EX5" | cut -d'|' -f1)"
      EX5_INSTALL_PATH="$(printf '%s\n' "$WITH_EX5" | cut -d'|' -f2)"
      say "見つかりました: $TERMINAL_DIR"
    else
      warn "既存の TickStreamer.ex5 を一意に特定できませんでした。"
      say "候補一覧（MQL5\\Experts を持つターミナル）:"
      i=0
      declare -a CANDIDATES=()
      while IFS='|' read -r dir ex5; do
        [[ -z "$dir" ]] && continue
        i=$((i+1))
        CANDIDATES+=("$dir")
        printf '    [%d] %s%s\n' "$i" "$dir" "$([[ -n "$ex5" ]] && echo "  (TickStreamer.ex5 あり)")"
      done <<<"$HITS"
      if [[ "${#CANDIDATES[@]}" -eq 0 ]]; then
        say "候補が見つかりませんでした。MT5 で ファイル → データフォルダを開く からパスを確認し、"
        say "貼り付けてください（例: C:\\Users\\you\\AppData\\Roaming\\MetaQuotes\\Terminal\\XXXXXXXX）。"
        ask TERMINAL_DIR "ターミナルのデータフォルダ:"
      else
        ask TERMINAL_DIR_INDEX "上の番号を入力してください:"
        TERMINAL_DIR="${CANDIDATES[$((TERMINAL_DIR_INDEX-1))]}"
      fi
      EX5_INSTALL_PATH="${TERMINAL_DIR}\\MQL5\\Experts\\TickStreamer.ex5"
    fi
    write_env TERMINAL_DIR "$TERMINAL_DIR"
    write_env EX5_INSTALL_PATH "$EX5_INSTALL_PATH"
  fi
  say "配置先: $EX5_INSTALL_PATH"

  COMPILE_LOG_WIN="${WIN_REPO_ROOT}\\benchmarks\\results\\compile.log"
  COMPILE_LOG_UNIX="$(to_unix_path "$COMPILE_LOG_WIN")"

  say "MetaEditor でコンパイルします（GUIは出ません。数秒かかります）..."
  run_ps1 "
    \$src = '${SRC_MQ5_WIN}'
    \$log = '${COMPILE_LOG_WIN}'
    \$exe = '${METAEDITOR_PATH}'
    Start-Process -FilePath \$exe -ArgumentList \"/compile:\`\"\$src\`\"\", \"/log:\`\"\$log\`\"\" -Wait -WindowStyle Hidden
  " >/dev/null

  # MetaEditor writes /log as UTF-16LE with CRLF line endings; convert to a
  # plain UTF-8 temp copy so tail/grep see text instead of NUL-interleaved bytes.
  COMPILE_LOG_UTF8="$(mktemp)"
  if [[ -f "$COMPILE_LOG_UNIX" ]]; then
    iconv -f UTF-16LE -t UTF-8 "$COMPILE_LOG_UNIX" 2>/dev/null | tr -d '\r' > "$COMPILE_LOG_UTF8" \
      || cp "$COMPILE_LOG_UNIX" "$COMPILE_LOG_UTF8"
    say "コンパイルログ（末尾）:"
    tail -n 8 "$COMPILE_LOG_UTF8" | sed 's/^/    /'
  else
    warn "ログファイルが生成されませんでした: $COMPILE_LOG_WIN"
  fi

  if ! grep -q "^Result: 0 errors" "$COMPILE_LOG_UTF8" 2>/dev/null; then
    warn "コンパイルエラーが発生した可能性があります（上のログを確認してください）。"
    confirm "それでも続行しますか？（推奨しません）" \
      || { warn "ソースを修正してから --mode $MODE --from-step 1 で再実行してください。"; exit 1; }
  else
    say "コンパイル成功（0 errors）。"
  fi
  rm -f "$COMPILE_LOG_UTF8"

  SRC_EX5_UNIX="$(to_unix_path "$SRC_EX5_WIN")"
  if [[ ! -f "$SRC_EX5_UNIX" ]]; then
    warn "コンパイル済み .ex5 が見つかりません: $SRC_EX5_WIN"
    exit 1
  fi

  EX5_INSTALL_UNIX="$(to_unix_path "$EX5_INSTALL_PATH")"
  if [[ -f "$EX5_INSTALL_UNIX" ]]; then
    BACKUP_PATH="${EX5_INSTALL_PATH}.bak-$(date +%Y%m%d-%H%M%S)"
    say "既存の .ex5 が見つかりました。バックアップしてから上書きします:"
    say "  上書き対象: $EX5_INSTALL_PATH"
    say "  バックアップ先: $BACKUP_PATH"
    confirm "上書きしてよいですか？" \
      || { warn "中断しました。--mode $MODE --from-step 1 で再開できます。"; exit 1; }
    cp "$EX5_INSTALL_UNIX" "$(to_unix_path "$BACKUP_PATH")"
    say "バックアップ完了。"
  fi
  cp "$SRC_EX5_UNIX" "$EX5_INSTALL_UNIX"
  say "配置完了: $EX5_INSTALL_PATH"

  if [[ "$MODE" == "after" ]]; then
    say "InpExtraMode=EXTRA_EVENT の計測に備え、TickSpy インジケータもコンパイル・配置します"
    say "（EXTRA_POLL だけを使うなら不要ですが、Stage 4/5〜8 で EVENT 計測を行うため必須です）。"
    SPY_SRC_MQ5_WIN="${WIN_REPO_ROOT}\\mql5\\Indicators\\TickStreamer\\TickSpy.mq5"
    SPY_SRC_EX5_WIN="${WIN_REPO_ROOT}\\mql5\\Indicators\\TickStreamer\\TickSpy.ex5"
    SPY_INSTALL_PATH="${TERMINAL_DIR}\\MQL5\\Indicators\\TickStreamer\\TickSpy.ex5"
    compile_and_install "$SPY_SRC_MQ5_WIN" "$SPY_SRC_EX5_WIN" "$SPY_INSTALL_PATH" "TickSpy"
    write_env SPY_INSTALL_PATH "$SPY_INSTALL_PATH"
    note "iCustom() はこの相対名で解決するため、サブフォルダ（TickStreamer\\）が名前の一部です"
    note "（MQL5\\Indicators\\TickSpy.ex5 に置いても見つかりません -- docs/troubleshooting.md 参照）。"
  fi

  say "MT5 のチャートで EA を再読み込みしてください:"
  step "対象チャートから EA を一度外す（右クリック → Expert Advisors → Remove）"
  step "ナビゲータの Expert Advisors から TickStreamer をチャートへ再ドラッグ"
  step "Inputs タブで Diagnostics グループの InpStatsSec を 30 に設定（この計測全体でこの値を使います）"
  if [[ "$MODE" == "baseline" ]]; then
    step "InpMeasureTickLoss は false のままにして OK"
  else
    step "InpVerbose は true のままにして OK（Stage 4 のログ確認に必要です）"
  fi
  note "もしくはターミナル自体を再起動しても構いません。"
  say "ツールボックスの「エキスパート」タブに次の形式の行が出るか確認してください:"
  if [[ "$MODE" == "baseline" ]]; then
    note "  [TickStreamer] last 30s: ... symbols=0 poll_n=... poll_us_avg=... poll_us_max=... poll_us_p99=... ping_us=..."
    note "  （InpMeasureTickLoss=false の間は extra_obs=/extra_sent= 等は出ません。Stage 4〜7 の loss=on 計測時のみ出ます）"
  else
    note "  [TickStreamer] last 30s: ... symbols=0 mode=poll poll_n=... poll_us_avg=... poll_us_max=... poll_us_p99=... ping_us=..."
    note "  ... extra_obs=... extra_sent=... ct_n=... ct_us_avg=... ct_us_max=... ct_err=... evt_n=... evt_us_avg=... evt_us_max=... evt_late=... evt_bad=..."
    note "  （HEAD では常にこれらが出ます。InpMeasureTickLoss という項目自体がありません。"
    note "  evt_* は InpExtraMode=EXTRA_POLL のままなら 0 のままで正常です -- EXTRA_EVENT に切り替えた時だけ増えます）"
  fi
  confirm "新しい統計行を確認できましたか？" \
    || { warn "確認できるまで進めないでください。EAの再読込をやり直すか、--mode $MODE --from-step 1 で再実行してください。"; exit 1; }
fi

# ============================================================================
# Stage 2 -- ブリッジ起動
# ============================================================================
if run_stage 2 "ブリッジ起動"; then
  say "mt5-ws-stream bridge を別ウィンドウで起動します。"
  say "既定ポート: feeder(EA接続)=9800 / ws・http(コンシューマ)=8765 -- EA の InpPort=9800 と一致している必要があります。"

  start_bridge_window

  confirm "ブリッジのウィンドウで起動ログ（listening ... など、エラーなし）を確認しましたか？" \
    || { warn "ブリッジが起動するまで先に進めないでください。"; exit 1; }

  say "MT5 側の Experts ログに [TickStreamer] connected to 127.0.0.1:9800 が出るはずです。"
  confirm "EA がブリッジに接続したことを確認しましたか？" \
    || { warn "接続を確認してから続けてください（Tools > Options > Expert Advisors の許可URLに 127.0.0.1 があるか、Algo Trading がONかも確認）。"; exit 1; }
fi

# ============================================================================
# Stage 3 -- Market Watch シンボルリストの取得
# ============================================================================
if run_stage 3 "Market Watch シンボルリストの取得"; then
  say "N=10 / N=50 で使う具体的なシンボルリストを、あなたの Market Watch から一度だけ取得します。"
  step "MT5 の Market Watch パネルで、必要なら右クリック → 「全シンボル表示 (Show All)」"
  step "1行目をクリックしてから最終行を Shift+クリックして全選択 → Ctrl+C でコピー"
  note "（コピーされる内容は Symbol / Bid / Ask などタブ区切りの複数列ですが、"
  note "  このウィザードは各行の先頭列（シンボル名）だけを使います）"
  ask_multiline MARKET_WATCH_RAW "コピーした内容をここに貼り付けてください（貼り付け後、空行のままEnterで確定）:"

  MARKET_WATCH_LIST="$(normalize_symbols "$(extract_symbols_from_paste "$MARKET_WATCH_RAW")")"
  TOTAL_SYM_COUNT=$(tr ',' '\n' <<<"$MARKET_WATCH_LIST" | grep -c '.' || true)

  if [[ -z "$MARKET_WATCH_LIST" ]]; then
    warn "シンボルを1つも読み取れませんでした。貼り付け内容を確認してやり直してください。"
    exit 1
  fi
  say "読み取ったシンボル数: $TOTAL_SYM_COUNT"
  if (( TOTAL_SYM_COUNT < 50 )); then
    warn "50銘柄未満です。N=50 は実際には ${TOTAL_SYM_COUNT} 銘柄で計測されます。"
  fi

  SYMLIST_10="$(first_n_symbols 10 "$MARKET_WATCH_LIST")"
  SYMLIST_50="$(first_n_symbols 50 "$MARKET_WATCH_LIST")"
  write_env MARKET_WATCH_LIST "$MARKET_WATCH_LIST"
  write_env SYMLIST_10 "$SYMLIST_10"
  write_env SYMLIST_50 "$SYMLIST_50"

  say "N=10 用のシンボルリスト:"
  note "  $SYMLIST_10"
  say "N=50 用のシンボルリスト:"
  note "  $SYMLIST_50"
  pause "確認したら Enter で次へ"
fi

# ============================================================================
# Stage 4 (after のみ) -- 動作チェックポイント: E1/E2/E3 の生きた検証
# ============================================================================
if [[ "$MODE" == "after" ]]; then
  if run_stage 4 "動作チェックポイント -- E1/E2/E3 の生きた検証"; then
    say "スイープ計測に入る前に、E1（構造リファクタ）・E2（全ティック配信）・E3（EXTRA_EVENT 配信）が"
    say "実機で期待どおり動いているかをチェックします。a〜h の8項目は個別に pass/fail を記録し、"
    say "FAIL があっても中断せず全項目を確認してから最後にまとめて判断します。"
    note "i（evt_late/evt_n 比）は pass/fail のない参考情報、j（N=all・EVENT でのメモリ/CPU）は"
    note "Stage 8（N=all）の EVENT 計測時にあわせて記録し、この結果ファイルに 4j として追記します。"

    # -- (a) 接続・チャート銘柄のティック/ハートビート・seq_gaps=0 --------
    say "[4a] 20秒間、チャート銘柄のティック/ハートビート受信と seq_gaps を確認します。"
    CHECKPOINT_CSV="$RESULTS_DIR/${MODE}-${RUN_DATE}-checkpoint.csv"
    say "  python benchmarks/symbol_scaling.py --seconds 20 --label checkpoint --csv \"$CHECKPOINT_CSV\""
    ( cd "$REPO_ROOT" && python benchmarks/symbol_scaling.py --seconds 20 --label "checkpoint" --csv "$CHECKPOINT_CSV" )
    note "（ダッシュボードで確認する場合は mt5-ws-stream dashboard でも代用できます）"
    say "上の表で、チャート銘柄のティックまたはハートビートが記録されているか、"
    say "\"seq_gaps (delta, REST)\" が 0 か確認してください。"
    write_env CHECKPOINT_CSV "$CHECKPOINT_CSV"
    record_check "4a" "EA がブリッジに接続し、チャート銘柄のティック/ハートビートを受信でき、seq_gaps=0 でしたか？"

    # -- (b) 切断→再接続ウォッチドッグ ------------------------------------
    say "[4b] ブリッジを一度停止し、再接続ウォッチドッグのログを確認します。"
    say "ブリッジのウィンドウで Ctrl-C を押して停止してください。"
    confirm "停止しましたか？" || { warn "中断しました。--mode after --from-step 4 で再開してください。"; exit 1; }
    say "MT5 の「エキスパート」タブに次のような行が出るはずです（InpVerbose=true が必要）:"
    note "  [TickStreamer] connection lost; reconnecting in <N> ms"
    ask_multiline CHECK_4B_LOST "上の行（切断検知〜再試行までの行）を貼り付けてください:"
    write_env CHECK_4B_LOST "$CHECK_4B_LOST"

    say "続けてブリッジを再起動します。"
    start_bridge_window
    confirm "ブリッジが起動しましたか？" || { warn "中断しました。"; exit 1; }
    say "再接続時に次のような行が出るはずです:"
    note "  [TickStreamer] connected to 127.0.0.1:9800"
    ask_multiline CHECK_4B_RECONNECT "上の行（再接続成功時の行）を貼り付けてください:"
    write_env CHECK_4B_RECONNECT "$CHECK_4B_RECONNECT"
    append_result "### チェック 4b 詳細 -- 再接続ウォッチドッグ" "切断検知:
\`\`\`
${CHECK_4B_LOST}
\`\`\`

再接続:
\`\`\`
${CHECK_4B_RECONNECT}
\`\`\`"
    record_check "4b" "切断ログ（connection lost; reconnecting）と再接続ログ（connected to）の両方を確認できましたか？"

    # -- (c) 起動時ウォームアップ（N=10）-----------------------------------
    say "[4c] 起動時ウォームアップのログを、追加銘柄10個（Stage 3 で取得した N=10）で確認します。"
    if [[ -z "${SYMLIST_10:-}" ]]; then
      warn "Stage 3 のシンボルリストが未取得です。--mode after --from-step 3 を先に実行してください。"
      exit 1
    fi
    say "InpSymbols に次の値を設定し、EA を再読込（OnInit を再実行）してください:"
    note "  $SYMLIST_10"
    step "F7 または右クリック → エキスパートアドバイザー → プロパティ"
    step "Inputs タブ → Symbols グループの InpSymbols に上記の値を貼り付け → OK"
    confirm "設定して再読込しましたか？" || { warn "中断しました。"; exit 1; }
    say "再読込直後の「エキスパート」タブに次の行が出るはずです:"
    note "  [TickStreamer] warmed up N of M extra symbols in X ms"
    note "  （1秒を超えて同期した銘柄があれば warm-up <SYMBOL> took N ms という行も出ます。無ければ省略可）"
    ask_multiline CHECK_4C_WARMUP "上の warmed up ... 行（と、あれば warm-up ... took 行）を貼り付けてください:"
    write_env CHECK_4C_WARMUP "$CHECK_4C_WARMUP"
    append_result "### チェック 4c 詳細 -- 起動時ウォームアップ（N=10）" "\`\`\`
${CHECK_4C_WARMUP}
\`\`\`"
    record_check "4c" "10銘柄分のウォームアップ行（warmed up 10 of 10 相当）を確認できましたか？"

    # -- (d) ct_err=0 / extra_obs-extra_sent の妥当性 ----------------------
    say "[4d] InpStatsSec の統計行（InpSymbols=N=10 のまま）で ct_err と extra_obs/extra_sent を確認します。"
    say "統計行が出るまで待ってから（InpStatsSec 秒後）、直近の行を貼り付けてください:"
    ask CHECK_4D_STATS "統計行を貼り付け:"
    write_env CHECK_4D_STATS "$CHECK_4D_STATS"
    say "確認ポイント:"
    note "  ct_err=0 であること（0でなければ CopyTicks が失敗し続けている銘柄がある可能性 -- troubleshooting.md 参照）"
    note "  extra_obs から extra_sent を引いた差は「ティックを受信した poll 1回・銘柄1つあたり約1件」程度が正常"
    note "  （CopyTicks の from は inclusive なので、直前に送った分の重複が毎回混じるのが仕様。極端に大きい差だけ疑ってください）"
    append_result "### チェック 4d 詳細 -- ct_err / extra_obs-extra_sent" "\`\`\`
${CHECK_4D_STATS}
\`\`\`"
    record_check "4d" "ct_err=0 かつ extra_obs-extra_sent の差が妥当な範囲でしたか？"

    # -- (e) 特定銘柄が extra_obs=0 に張り付いていないか --------------------
    say "[4e] Market Watch で値が動いているのに配信が止まっている銘柄がないか確認します。"
    say "4a または直近の symbol_scaling.py の表（$CHECKPOINT_CSV / 上の出力）で、"
    say "各銘柄の Ticks 列を見てください。Market Watch 上で Bid/Ask が動いているのに"
    say "Ticks が 0 のままの銘柄があれば、その銘柄の CopyTicks 配信が壊れているサインです"
    note "（ウォームアップ失敗や ct_err の連続発生が疑われます -- troubleshooting.md の「ct_err climbing」参照）。"
    record_check "4e" "Market Watch では値が動いているのに Ticks=0 のままの銘柄はありませんでしたか（＝そのような銘柄が無いことを確認）？"

    # -- (f) 起動ログの timer= が InpPollMs と一致 ---------------------------
    say "[4f] 起動時ログの timer= が InpPollMs の設定値と一致しているか確認します"
    say "（この時点では InpExtraMode はまだ既定の EXTRA_POLL のはずです）。"
    say "起動時（OnInit）のログ行を貼り付けてください:"
    note "  [TickStreamer] started chart=... extra_symbols=... mode=poll timer=<N>ms stats=...s server_utc_offset=..."
    ask CHECK_4F_STARTLINE "started ... の行を貼り付けてください:"
    write_env CHECK_4F_STARTLINE "$CHECK_4F_STARTLINE"
    append_result "### チェック 4f 詳細 -- 起動ログの timer=" "\`\`\`
${CHECK_4F_STARTLINE}
\`\`\`"
    record_check "4f" "mode=poll かつ timer=<N>ms が InpPollMs の設定値と一致していましたか？"

    # -- (g)(h) EXTRA_EVENT へ切り替え、evt_n=0 / evt_bad の生きた検証 -------
    say "[4g/4h] InpExtraMode を EXTRA_EVENT に切り替え、TickSpy が実際にこのターミナルで"
    say "発火しているかを確認します（InpSymbols は N=10 のまま変更しません）。"
    step "F7 → Inputs タブ → Symbols グループの InpExtraMode を EXTRA_EVENT へ → OK"
    note "OK で再初期化されます。"
    confirm "InpExtraMode=EXTRA_EVENT に変更して再読込しましたか？" || { warn "中断しました。"; exit 1; }

    say "再読込直後の起動ログ（started ...）を貼り付けてください（mode=event になっているはずです）:"
    note "  [TickStreamer] started chart=... extra_symbols=10 mode=event timer=<InpEventBackstopMs>ms ..."
    note "  「no tick spy for ...」という行が出ていたら TickSpy.ex5 が未配置/未コンパイルです"
    note "  -- Stage 1 の TickSpy 配置をやり直すか docs/troubleshooting.md を参照してください。"
    ask CHECK_4G_STARTLINE "started ... の行を貼り付けてください:"
    write_env CHECK_4G_STARTLINE "$CHECK_4G_STARTLINE"
    append_result "### チェック 4g/4h 詳細 -- 起動ログ（mode=event）" "\`\`\`
${CHECK_4G_STARTLINE}
\`\`\`"
    if [[ "$CHECK_4G_STARTLINE" != *"mode=event"* ]]; then
      warn "started 行に mode=event が見つかりません。InpExtraMode の変更が反映されていない可能性があります。"
    fi

    say "InpStatsSec（30秒）を1回以上経過させてから、直近の統計行を貼り付けてください。"
    say "60秒待ちます..."
    sleep 60
    ask CHECK_4GHI_STATS "統計行を貼り付け:"
    write_env CHECK_4GHI_STATS "$CHECK_4GHI_STATS"
    append_result "### チェック 4g/4h/4i 詳細 -- EXTRA_EVENT 統計行" "\`\`\`
${CHECK_4GHI_STATS}
\`\`\`"

    EVT_N="$(grep -oE 'evt_n=[0-9]+' <<<"$CHECK_4GHI_STATS" | head -n1 | cut -d= -f2)"
    EVT_BAD="$(grep -oE 'evt_bad=[0-9]+' <<<"$CHECK_4GHI_STATS" | head -n1 | cut -d= -f2)"
    EVT_LATE="$(grep -oE 'evt_late=[0-9]+' <<<"$CHECK_4GHI_STATS" | head -n1 | cut -d= -f2)"
    EXTRA_SENT="$(grep -oE 'extra_sent=[0-9]+' <<<"$CHECK_4GHI_STATS" | head -n1 | cut -d= -f2)"

    if [[ -z "$EVT_N" || -z "$EVT_BAD" ]]; then
      warn "統計行から evt_n / evt_bad を自動抽出できませんでした（貼り付け内容を確認してください）。手動で判定します。"
      record_check "4g" "evt_n > 0 でしたか？（evt_n=0 かつ extra_sent=0 なら閑散相場なので FAIL にせず、しばらく待って再計測してください）"
      record_check "4h" "evt_bad=0 でしたか？"
    else
      say "抽出結果: evt_n=${EVT_N} evt_bad=${EVT_BAD} evt_late=${EVT_LATE:-n/a} extra_sent=${EXTRA_SENT:-n/a}"
      if [[ "$EVT_N" -gt 0 ]]; then
        append_result "### チェック 4g" "結果: PASS (evt_n=${EVT_N})"
      elif [[ "${EXTRA_SENT:-0}" -eq 0 ]]; then
        warn "evt_n=0 かつ extra_sent=0 です -- 閑散相場でティック自体が来ていない可能性があります（troubleshooting.md 参照）。"
        say "60秒待って上の統計行を取り直すことを検討してください。それでも FAIL として記録しますか？"
        if confirm "4g を FAIL として記録しますか？（推奨: いいえ→--mode after --from-step 4 で再計測）"; then
          CHECK_FAIL_COUNT=$((CHECK_FAIL_COUNT + 1))
          append_result "### チェック 4g" "結果: FAIL (evt_n=0, extra_sent=0 -- 閑散相場の可能性あり)"
        else
          append_result "### チェック 4g" "結果: 保留（evt_n=0, extra_sent=0 -- 閑散相場のため再計測推奨）"
        fi
      else
        CHECK_FAIL_COUNT=$((CHECK_FAIL_COUNT + 1))
        append_result "### チェック 4g" "結果: FAIL -- spy OnCalculate does not fire for chart-less symbols（evt_n=0 だが extra_sent=${EXTRA_SENT} -- market is not quiet; live-checkpoint item #1）"
        warn "チェック 4g を FAIL として記録しました（spy OnCalculate does not fire for chart-less symbols）。"
      fi

      if [[ "$EVT_BAD" -eq 0 ]]; then
        append_result "### チェック 4h" "結果: PASS (evt_bad=0)"
      else
        CHECK_FAIL_COUNT=$((CHECK_FAIL_COUNT + 1))
        append_result "### チェック 4h" "結果: FAIL (evt_bad=${EVT_BAD})"
        warn "チェック 4h を FAIL として記録しました（evt_bad=${EVT_BAD}）。"
      fi
    fi

    # -- (i) evt_late/evt_n 比（pass/fail なし、参考情報） -------------------
    if [[ -n "${EVT_N:-}" && -n "${EVT_LATE:-}" && "$EVT_N" -gt 0 ]]; then
      EVT_LATE_RATIO="$(awk -v n="$EVT_N" -v l="$EVT_LATE" 'BEGIN{printf "%.2f", l/n}')"
      write_env CHECK_4I_RATIO "$EVT_LATE_RATIO"
      append_result "### チェック 4i -- evt_late/evt_n 比" "evt_late=${EVT_LATE} / evt_n=${EVT_N} = ${EVT_LATE_RATIO}

比が1に近いほど、バックストップ（タイマー）または直前のイベントがスパイより先に同じティックを
回収しており、EXTRA_EVENT の恩恵（レイテンシ短縮）が小さいことを意味します。0に近いほど
スパイ自体がティックを取りに行けています（pass/fail の対象ではなく参考情報です）。"
      say "[4i] evt_late/evt_n = ${EVT_LATE_RATIO}（1に近い＝バックストップが先着＝EVENTの効果が薄い、0に近い＝EVENTが効いている）"
    else
      append_result "### チェック 4i -- evt_late/evt_n 比" "evt_n=0（または未取得）のため算出できません。"
    fi

    # -- (j) N=all・EVENT でのメモリ/CPU（pass/fail なし、Stage 8 で記録） --
    note "[4j] N=all・EXTRA_EVENT での端末メモリ/CPU使用量は、Stage 8（N=all）の EVENT 計測直後に"
    note "     まとめて記録します（ここではまだ計測していません）。"

    if (( CHECK_FAIL_COUNT > 0 )); then
      warn "${CHECK_FAIL_COUNT} 件のチェックが FAIL でした（$RESULTS_MD に詳細を記録済み）。"
      confirm "FAIL があってもスイープ計測（Stage 5〜）に進みますか？" \
        || { warn "中断しました。EA/ブリッジの設定を見直してから --mode after --from-step 4 で再実行してください。"; exit 1; }
    else
      say "a〜h の8項目すべて PASS でした。"
    fi
  fi
fi

# ============================================================================
# 計測の共通処理（N=1/10/50/all のスイープ stage から呼び出す）
# ============================================================================
# measure_n KEY LABEL INP_SYMBOLS_VALUE DESCRIPTION
#
# baseline: 二回計測（InpMeasureTickLoss を loss=off → loss=on）。
# after:    二回計測（InpExtraMode を EXTRA_POLL → EXTRA_EVENT）。
#           InpMeasureTickLoss は存在しない。
measure_n() {
  local key="$1" label="$2" inp_value="$3" desc="$4"

  say "InpSymbols を次の値に設定してください:"
  if [[ -z "$inp_value" ]]; then
    note "  （空欄のまま -- チャート銘柄のみ）"
  else
    note "  $inp_value"
  fi
  say "$desc"
  step "チャート上で F7、または右クリック → エキスパートアドバイザー → プロパティ"
  step "Inputs タブ → Symbols グループの InpSymbols に上記の値を貼り付け"
  if [[ "$MODE" == "baseline" ]]; then
    step "Diagnostics グループの InpMeasureTickLoss は false のままにして OK"
  else
    step "同じ Inputs タブで InpExtraMode を EXTRA_POLL に設定 → OK（まず POLL から計測します。"
    step "  Stage 4 の直後は EXTRA_EVENT が残っているはずなので、ここで戻してください）"
  fi
  note "OK を押すと EA が再初期化され（OnInit 再実行）、再接続します。"
  confirm "設定を反映しましたか？" || { warn "中断しました。--mode $MODE --from-step でこのステージから再開してください。"; exit 1; }

  say "60秒のウォームアップ待機中（タイマーとティック受信が安定するのを待ちます）..."
  sleep 60

  if [[ "$MODE" == "baseline" ]]; then
    local csv_off="$RESULTS_DIR/${MODE}-${RUN_DATE}-${key}-lossoff.csv"
    say "計測開始（loss=off, 60秒）:"
    note "  python benchmarks/symbol_scaling.py --seconds 60 --label \"${label} loss=off\" --csv \"$csv_off\""
    ( cd "$REPO_ROOT" && python benchmarks/symbol_scaling.py --seconds 60 --label "${label} loss=off" --csv "$csv_off" )

    say "MT5の「エキスパート」タブ（ツールボックス）に出た直近の [TickStreamer] last ...s: ... 行をコピーしてください。"
    local statvar_off="STATS_${key}_LOSSOFF"
    ask "$statvar_off" "統計行を貼り付け:"
    write_env "$statvar_off" "${!statvar_off}"
    append_result "### ${label} -- loss=off" "\`${!statvar_off}\`

csv: \`${csv_off}\`"

    say "続けて InpMeasureTickLoss を true に変更してください（InpSymbols は変更しないでください）。"
    step "F7 → Inputs タブ → Diagnostics → InpMeasureTickLoss = true → OK"
    note "OK で再初期化されます。最初に出る統計行は CopyTicks の初回同期（最大45秒ブロック）を含むため計測になりません -- 無視してください。"
    confirm "設定を反映しましたか？" || { warn "中断しました。"; exit 1; }

    say "1回目の統計行（無効な計測）を読み飛ばすため60秒待ちます..."
    sleep 60

    local csv_on="$RESULTS_DIR/${MODE}-${RUN_DATE}-${key}-losson.csv"
    say "計測開始（loss=on, 60秒）:"
    note "  python benchmarks/symbol_scaling.py --seconds 60 --label \"${label} loss=on\" --csv \"$csv_on\""
    ( cd "$REPO_ROOT" && python benchmarks/symbol_scaling.py --seconds 60 --label "${label} loss=on" --csv "$csv_on" )

    say "先ほどの1回目（起動直後）ではなく、直近に出た統計行をコピーしてください。"
    local statvar_on="STATS_${key}_LOSSON"
    ask "$statvar_on" "統計行を貼り付け:"
    write_env "$statvar_on" "${!statvar_on}"
    append_result "### ${label} -- loss=on" "\`${!statvar_on}\`

csv: \`${csv_on}\`"

    say "次のNに備えて InpMeasureTickLoss を false に戻してください。"
    step "F7 → Inputs → InpMeasureTickLoss = false → OK"
    pause "戻したら Enter で次へ"
  else
    # Leg 1: EXTRA_POLL (already set by the OK above).
    _measure_after_leg "$key" "$label" "poll"

    # Leg 2: EXTRA_EVENT, same InpSymbols.
    say "続けて InpExtraMode を EXTRA_EVENT に切り替えてください（InpSymbols は変更しないでください）。"
    step "F7 → Inputs タブ → Symbols → InpExtraMode = EXTRA_EVENT → OK"
    note "OK で再初期化されます。「no tick spy for ...」という行が出たら TickSpy.ex5 が未配置/未コンパイルです。"
    confirm "設定を反映しましたか？" || { warn "中断しました。--mode $MODE --from-step でこのステージから再開してください。"; exit 1; }

    say "60秒のウォームアップ待機中..."
    sleep 60
    _measure_after_leg "$key" "$label" "event"

    if [[ "$key" == "Nall" ]]; then
      say "[4j] N=all・EXTRA_EVENT での端末メモリ/CPU使用量を確認します（今 InpExtraMode=EXTRA_EVENT のはずです）。"
      say "タスクマネージャーで terminal64.exe のメモリ・CPU使用率を確認してください。"
      ask_multiline CHECK_4J_TASKMGR "タスクマネージャーの読み取り値を貼り付けてください（例: terminal64.exe  512.3 MB  3-8% CPU）:"
      write_env CHECK_4J_TASKMGR "$CHECK_4J_TASKMGR"
      append_result "### チェック 4j -- N=all・EVENT でのメモリ/CPU" "\`\`\`
${CHECK_4J_TASKMGR}
\`\`\`

pass/fail の対象ではなく参考情報です。"
      say "この値は動作チェックポイント（Stage 4）の一部として 4j に記録されました。"
    fi

    say "次のNに備えて InpExtraMode を EXTRA_POLL に戻してください。"
    step "F7 → Inputs → InpExtraMode = EXTRA_POLL → OK"
    confirm "戻しましたか？" || { warn "中断しました。"; exit 1; }
    pause "確認したら Enter で次へ"
  fi
}

# _measure_after_leg KEY LABEL MODE_WORD -- after-mode-only: runs one 60s
# symbol_scaling.py capture and records the pasted stats line for one
# InpExtraMode leg (mode_word is "poll" or "event"). Called twice from
# measure_n's after-branch so every N is measured under both delivery modes
# in the same InpSymbols setting.
_measure_after_leg() {
  local key="$1" label="$2" mode_word="$3"
  local csv="$RESULTS_DIR/${MODE}-${RUN_DATE}-${key}-${mode_word}.csv"
  say "計測開始（${mode_word}, 60秒）:"
  note "  python benchmarks/symbol_scaling.py --seconds 60 --label \"${label} after ${mode_word}\" --csv \"$csv\""
  ( cd "$REPO_ROOT" && python benchmarks/symbol_scaling.py --seconds 60 --label "${label} after ${mode_word}" --csv "$csv" )

  say "MT5の「エキスパート」タブ（ツールボックス）に出た直近の [TickStreamer] last ...s: ... 行をコピーしてください。"
  note "  （mode=${mode_word} になっているか確認してください。event のはずが mode=poll のままなら iCustom 失敗の可能性"
  note "  -- 「no tick spy for ...」が出ていないか、docs/troubleshooting.md も確認してください）"
  local statvar="STATS_${key}_$(tr '[:lower:]' '[:upper:]' <<<"$mode_word")"
  ask "$statvar" "統計行を貼り付け:"
  write_env "$statvar" "${!statvar}"
  append_result "### ${label} after ${mode_word}" "\`${!statvar}\`

csv: \`${csv}\`"
}

# ============================================================================
# Stage: N=1（チャートのみ）
# ============================================================================
if [[ "$MODE" == "baseline" ]]; then SWEEP_STAGE_N1=4; else SWEEP_STAGE_N1=5; fi
if run_stage "$SWEEP_STAGE_N1" "N=1（チャートのみ）計測"; then
  say "N=1 は「追加シンボル無し」、つまり InpSymbols を空欄にした状態です。"
  if [[ "$MODE" == "baseline" ]]; then
    note "poll_n=0 / ticks_lost=0（あるいは n/a）になるのが正常です -- 追加シンボルのポーリング自体が発生しないため。"
  else
    note "poll_n=0 / extra_obs=0 / extra_sent=0（あるいは n/a）になるのが正常です -- 追加シンボルのポーリング自体が発生しないため。"
  fi
  measure_n "N1" "N=1" "" "InpSymbols を空欄のままにしてください（チャート銘柄は OnTick で常に配信されます）。"
fi

# ============================================================================
# Stage: N=10
# ============================================================================
if [[ "$MODE" == "baseline" ]]; then SWEEP_STAGE_N10=5; else SWEEP_STAGE_N10=6; fi
if run_stage "$SWEEP_STAGE_N10" "N=10 計測"; then
  if [[ -z "${SYMLIST_10:-}" ]]; then
    warn "Stage 3 のシンボルリストが未取得です。--mode $MODE --from-step 3 を先に実行してください。"
    exit 1
  fi
  measure_n "N10" "N=10" "$SYMLIST_10" "Market Watch の先頭10銘柄です（Stage 3 で取得）。"
fi

# ============================================================================
# Stage: N=50
# ============================================================================
if [[ "$MODE" == "baseline" ]]; then SWEEP_STAGE_N50=6; else SWEEP_STAGE_N50=7; fi
if run_stage "$SWEEP_STAGE_N50" "N=50 計測"; then
  if [[ -z "${SYMLIST_50:-}" ]]; then
    warn "Stage 3 のシンボルリストが未取得です。--mode $MODE --from-step 3 を先に実行してください。"
    exit 1
  fi
  measure_n "N50" "N=50" "$SYMLIST_50" "Market Watch の先頭50銘柄です（Stage 3 で取得。50銘柄未満の場合は取得できた全数）。"
fi

# ============================================================================
# Stage: N=all（*）
# ============================================================================
if [[ "$MODE" == "baseline" ]]; then SWEEP_STAGE_NALL=7; else SWEEP_STAGE_NALL=8; fi
if run_stage "$SWEEP_STAGE_NALL" "N=all（*）計測"; then
  measure_n "Nall" "N=all" "*" "アスタリスク1文字です。現在 Market Watch に表示されている全銘柄が対象になります。"
fi

# ============================================================================
# Stage 9 (after のみ) -- オフライン ground truth（N=10 の受信窓を記録）
# ============================================================================
if [[ "$MODE" == "after" ]]; then
  if run_stage 9 "オフライン ground truth -- N=10 の ticks lost を算出"; then
    say "docs/latency.md の Symbol scaling table には「ticks lost (ground truth)」列があります。"
    say "これは EA 自身のカウンタでは測れません（実装が自分自身の証人にはなれないため）。"
    say "手順は、対象区間について:"
    note "  1. ワイヤ側のティック数 -- このウィザードが symbol_scaling.py の表から記録します。"
    note "  2. 端末側のティック数 -- mql5/Scripts/TickStreamer/CountTicks.mq5 が"
    note "     CopyTicksRange(sym, buf, COPY_TICKS_ALL, t0*1000, t1*1000) を同じ区間に対して呼びます。"
    note "  3. benchmarks/compare_tick_counts.py が両者を突き合わせ、ticks_lost を計算します。"

    if [[ -z "${SYMLIST_10:-}" ]]; then
      warn "Stage 3 のシンボルリストが未取得です。--mode after --from-step 3 を先に実行してください。"
      exit 1
    fi
    if [[ -z "${METAEDITOR_PATH:-}" || -z "${TERMINAL_DIR:-}" ]]; then
      warn "MetaEditor / ターミナルデータフォルダが未確定です。--mode after --from-step 1 を先に実行してください。"
      exit 1
    fi

    say "InpSymbols を N=10 のリストに、InpExtraMode を EXTRA_POLL に戻してください"
    say "（Stage 8 の直後は EVENT 側が残っている可能性があります。ground truth の必須計測は POLL で行います）:"
    note "  InpSymbols   = $SYMLIST_10"
    note "  InpExtraMode = EXTRA_POLL"
    step "F7 → Inputs → Symbols → InpSymbols / InpExtraMode を上記のとおりに → OK"
    confirm "InpSymbols=N=10 かつ InpExtraMode=EXTRA_POLL になっていることを確認しましたか？" || { warn "中断しました。"; exit 1; }

    say "CountTicks スクリプトをコンパイルし、ターミナルに配置します。"
    SCRIPT_SRC_MQ5_WIN="${WIN_REPO_ROOT}\\mql5\\Scripts\\TickStreamer\\CountTicks.mq5"
    SCRIPT_SRC_EX5_WIN="${WIN_REPO_ROOT}\\mql5\\Scripts\\TickStreamer\\CountTicks.ex5"
    SCRIPT_INSTALL_PATH="${TERMINAL_DIR}\\MQL5\\Scripts\\TickStreamer\\CountTicks.ex5"
    compile_and_install "$SCRIPT_SRC_MQ5_WIN" "$SCRIPT_SRC_EX5_WIN" "$SCRIPT_INSTALL_PATH" "CountTicks"
    write_env SCRIPT_INSTALL_PATH "$SCRIPT_INSTALL_PATH"
    say "ナビゲータ（Ctrl+N）の Scripts に TickStreamer → CountTicks が現れるはずです。"
    step "見つからなければナビゲータを右クリック → 更新"
    confirm "ナビゲータに CountTicks が表示されていますか？" \
      || { warn "中断しました。--mode after --from-step 9 で再開してください。"; exit 1; }

    say "30秒のウォームアップ待機中..."
    sleep 30

    # Millisecond-precision epoch is captured directly (not seconds * 1000):
    # CountTicks.mq5's window is only as tight as this capture, and rounding
    # to a whole second would add up to ~1s of its own slop on top of the
    # poll-period slop the header comment already accounts for.
    GT_N10_T0="$(date -u +'%Y-%m-%dT%H:%M:%S.%3NZ')"
    GT_FROM_MSC="$(date -u +%s%3N)"
    GT_N10_T0_EPOCH="$(( GT_FROM_MSC / 1000 ))"
    GT_CSV="$RESULTS_DIR/${MODE}-${RUN_DATE}-N10-groundtruth.csv"
    say "計測開始（30秒、ground truth 用 -- wire 側）:"
    note "  python benchmarks/symbol_scaling.py --seconds 30 --label \"N=10 ground-truth window\" --csv \"$GT_CSV\""
    ( cd "$REPO_ROOT" && python benchmarks/symbol_scaling.py --seconds 30 --label "N=10 ground-truth window" --csv "$GT_CSV" )
    GT_N10_T1="$(date -u +'%Y-%m-%dT%H:%M:%S.%3NZ')"
    GT_TO_MSC="$(date -u +%s%3N)"
    GT_N10_T1_EPOCH="$(( GT_TO_MSC / 1000 ))"

    write_env GT_N10_T0 "$GT_N10_T0"
    write_env GT_N10_T0_EPOCH "$GT_N10_T0_EPOCH"
    write_env GT_N10_T1 "$GT_N10_T1"
    write_env GT_N10_T1_EPOCH "$GT_N10_T1_EPOCH"
    write_env GT_CSV "$GT_CSV"
    write_env GT_FROM_MSC "$GT_FROM_MSC"
    write_env GT_TO_MSC "$GT_TO_MSC"

    say "上の表の Symbol / Ticks 列（ワイヤ側のティック数、区間30秒）が wire 側の値です。"
    say "同じ区間について、端末側（CopyTicksRange）でも数えます。"
    say "ナビゲータの Scripts → TickStreamer → CountTicks をチャートへドラッグしてください。"
    say "Inputs ダイアログで次のとおり設定してください:"
    note "  Window / InpFromMsc = $GT_FROM_MSC"
    note "  Window / InpToMsc   = $GT_TO_MSC"
    note "  Symbols / InpSymbols = $SYMLIST_10"
    note "  Options / InpFlags   = COPY_TICKS_ALL（既定のままで OK）"
    note "  Options / InpCsvFile = TickStreamer_counts.csv（既定のままで OK）"
    warn "symbol_scaling.py は全銘柄（チャート銘柄含む）を購読するため、wire 側の TOTAL には"
    warn "チャート銘柄のぶんも入っています。InpSymbols がチャート銘柄を含んでいない場合は、"
    warn "上記の値の先頭にチャート銘柄をカンマ区切りで足してください（例: EURUSD,$SYMLIST_10）。"
    note "  同じ銘柄が二重に入っても数え直されるだけで安全です（同じ回答になります）。"
    step "OK を押すとスクリプトはすぐに実行され、終了すると自動的に外れます（EAと違い常駐しません）"
    say "「エキスパート」タブに [TickStreamer][CountTicks] ... done: ... という行が出れば完了です。"
    confirm "CountTicks の実行が完了したことを確認しましたか？" \
      || { warn "中断しました。--mode after --from-step 9 で再開してください。"; exit 1; }

    GT_TERMINAL_CSV="${TERMINAL_DIR}\\MQL5\\Files\\TickStreamer_counts.csv"
    write_env GT_TERMINAL_CSV "$GT_TERMINAL_CSV" >/dev/null
    say "端末側の結果 CSV は既定で次の場所に書き出されます（InpCsvFile を変えていなければ）:"
    note "  $GT_TERMINAL_CSV"
    ask GT_TERMINAL_CSV "パスが異なる場合は入力し直してください（Enterでそのまま）:"
    write_env GT_TERMINAL_CSV "$GT_TERMINAL_CSV"

    GT_TERMINAL_CSV_UNIX="$(to_unix_path "$GT_TERMINAL_CSV")"
    if [[ ! -f "$GT_TERMINAL_CSV_UNIX" ]]; then
      warn "ファイルが見つかりません: $GT_TERMINAL_CSV"
      confirm "それでも突き合わせを試みますか？（失敗します）" \
        || { warn "中断しました。--mode after --from-step 9 で再開してください。"; exit 1; }
    fi

    GT_COMPARE_TXT="$RESULTS_DIR/${MODE}-${RUN_DATE}-N10-groundtruth-compare.txt"
    say "wire 側と端末側を突き合わせます:"
    note "  python benchmarks/compare_tick_counts.py --wire \"$GT_CSV\" --terminal \"$GT_TERMINAL_CSV_UNIX\""
    if ( cd "$REPO_ROOT" && python benchmarks/compare_tick_counts.py \
           --wire "$GT_CSV" --terminal "$GT_TERMINAL_CSV_UNIX" > "$GT_COMPARE_TXT" ); then
      sed 's/^/    /' "$GT_COMPARE_TXT"
      write_env GT_COMPARE_TXT "$GT_COMPARE_TXT"

      append_result "### N=10 ground truth -- ticks lost" "- 受信窓 開始 (UTC): \`${GT_N10_T0}\` (epoch ${GT_N10_T0_EPOCH}, InpFromMsc=${GT_FROM_MSC})
- 受信窓 終了 (UTC): \`${GT_N10_T1}\` (epoch ${GT_N10_T1_EPOCH}, InpToMsc=${GT_TO_MSC})
- wire 側 CSV: \`${GT_CSV}\`
- 端末側 CSV: \`${GT_TERMINAL_CSV}\`

\`\`\`
$(cat "$GT_COMPARE_TXT")
\`\`\`

lost 列が銘柄ごとに 0 でなければ、docs/latency.md の \"time_msc の境界が wire 側の受信時刻とずれる\"
（このスクリプトのヘッダコメント参照）による許容誤差の範囲かどうかを確認してください。"
      say "docs/latency.md の Symbol scaling table の「ticks lost (ground truth)」列にこの結果を反映してください。"
    else
      warn "compare_tick_counts.py の実行に失敗しました。上のパスを確認してから"
      warn "--mode after --from-step 9 で再実行してください。"
      exit 1
    fi

    # -- 任意: EXTRA_EVENT でも同じ ground truth を追加計測（軽いので推奨） --
    if confirm "EXTRA_EVENT モードでも同じ ground truth 計測を追加で行いますか？（任意・同じ手順をもう一度）"; then
      say "InpExtraMode を EXTRA_EVENT に切り替えてください（InpSymbols は N=10 のまま）。"
      step "F7 → Inputs → Symbols → InpExtraMode = EXTRA_EVENT → OK"
      if ! confirm "設定を反映しましたか？"; then
        warn "EVENT側の ground truth は省略します。"
      else

      say "30秒のウォームアップ待機中..."
      sleep 30

      GT_N10_T0_EVENT="$(date -u +'%Y-%m-%dT%H:%M:%S.%3NZ')"
      GT_FROM_MSC_EVENT="$(date -u +%s%3N)"
      GT_N10_T0_EPOCH_EVENT="$(( GT_FROM_MSC_EVENT / 1000 ))"
      GT_CSV_EVENT="$RESULTS_DIR/${MODE}-${RUN_DATE}-N10-groundtruth-event.csv"
      say "計測開始（30秒、ground truth 用 -- wire 側、EXTRA_EVENT）:"
      note "  python benchmarks/symbol_scaling.py --seconds 30 --label \"N=10 ground-truth window (event)\" --csv \"$GT_CSV_EVENT\""
      ( cd "$REPO_ROOT" && python benchmarks/symbol_scaling.py --seconds 30 --label "N=10 ground-truth window (event)" --csv "$GT_CSV_EVENT" )
      GT_N10_T1_EVENT="$(date -u +'%Y-%m-%dT%H:%M:%S.%3NZ')"
      GT_TO_MSC_EVENT="$(date -u +%s%3N)"
      GT_N10_T1_EPOCH_EVENT="$(( GT_TO_MSC_EVENT / 1000 ))"

      write_env GT_N10_T0_EVENT "$GT_N10_T0_EVENT"
      write_env GT_N10_T0_EPOCH_EVENT "$GT_N10_T0_EPOCH_EVENT"
      write_env GT_N10_T1_EVENT "$GT_N10_T1_EVENT"
      write_env GT_N10_T1_EPOCH_EVENT "$GT_N10_T1_EPOCH_EVENT"
      write_env GT_CSV_EVENT "$GT_CSV_EVENT"
      write_env GT_FROM_MSC_EVENT "$GT_FROM_MSC_EVENT"
      write_env GT_TO_MSC_EVENT "$GT_TO_MSC_EVENT"

      say "先ほどと同じ手順で CountTicks をもう一度実行してください。窓だけ今回の値に変えてください:"
      note "  Window / InpFromMsc = $GT_FROM_MSC_EVENT"
      note "  Window / InpToMsc   = $GT_TO_MSC_EVENT"
      note "  Symbols / InpSymbols = $SYMLIST_10"
      confirm "CountTicks（EVENT側の窓）の実行が完了したことを確認しましたか？" \
        || warn "EVENT側の ground truth 突き合わせを省略します（必須ではありません）。"

      GT_TERMINAL_CSV_EVENT="${TERMINAL_DIR}\\MQL5\\Files\\TickStreamer_counts.csv"
      say "端末側の結果 CSV（既定のパス、直前の実行で上書きされています）:"
      note "  $GT_TERMINAL_CSV_EVENT"
      ask GT_TERMINAL_CSV_EVENT "パスが異なる場合は入力し直してください（Enterでそのまま）:"
      write_env GT_TERMINAL_CSV_EVENT "$GT_TERMINAL_CSV_EVENT"

      GT_TERMINAL_CSV_EVENT_UNIX="$(to_unix_path "$GT_TERMINAL_CSV_EVENT")"
      GT_COMPARE_TXT_EVENT="$RESULTS_DIR/${MODE}-${RUN_DATE}-N10-groundtruth-event-compare.txt"
      if [[ -f "$GT_TERMINAL_CSV_EVENT_UNIX" ]] && ( cd "$REPO_ROOT" && python benchmarks/compare_tick_counts.py \
             --wire "$GT_CSV_EVENT" --terminal "$GT_TERMINAL_CSV_EVENT_UNIX" > "$GT_COMPARE_TXT_EVENT" ); then
        sed 's/^/    /' "$GT_COMPARE_TXT_EVENT"
        write_env GT_COMPARE_TXT_EVENT "$GT_COMPARE_TXT_EVENT"
        append_result "### N=10 ground truth (EXTRA_EVENT) -- ticks lost" "- 受信窓 開始 (UTC): \`${GT_N10_T0_EVENT}\` (epoch ${GT_N10_T0_EPOCH_EVENT}, InpFromMsc=${GT_FROM_MSC_EVENT})
- 受信窓 終了 (UTC): \`${GT_N10_T1_EVENT}\` (epoch ${GT_N10_T1_EPOCH_EVENT}, InpToMsc=${GT_TO_MSC_EVENT})
- wire 側 CSV: \`${GT_CSV_EVENT}\`
- 端末側 CSV: \`${GT_TERMINAL_CSV_EVENT}\`

\`\`\`
$(cat "$GT_COMPARE_TXT_EVENT")
\`\`\`"
        say "docs/latency.md の Symbol scaling table（event 行）の「ticks lost (ground truth)」列にも反映してください。"
      else
        warn "EVENT側の ground truth 突き合わせに失敗またはスキップしました（任意の手順なので先へ進みます）。"
      fi

      say "InpExtraMode を EXTRA_POLL に戻してください（次のステージのため）。"
      step "F7 → Inputs → InpExtraMode = EXTRA_POLL → OK"
      pause "戻したら Enter で次へ"
      fi
    fi
  fi
fi

# ============================================================================
# Stage: まとめ
# ============================================================================
if [[ "$MODE" == "baseline" ]]; then SUMMARY_STAGE=8; else SUMMARY_STAGE=10; fi
if run_stage "$SUMMARY_STAGE" "まとめ"; then
  if [[ "$MODE" == "baseline" ]]; then
    say "ベースライン（E0=760f2c3）計測が完了しました。"
    say "結果ファイル: $RESULTS_MD"
    say "各回の CSV: $RESULTS_DIR/${MODE}-${RUN_DATE}-*-loss{off,on}.csv"
    note "この結果は改修前（before）の値です。--mode after で同じ手順（動作チェックポイント込み）を実行し、"
    note "docs/latency.md の Symbol scaling table（N × {p50, p99, timer callback µs, ticks lost}）を更新してください。"
    note "InpMeasureTickLoss は E0 だけの診断用フラグです。HEAD には存在しません。"
  else
    say "after（HEAD, E1+E2+E3）計測が完了しました。"
    say "結果ファイル: $RESULTS_MD"
    say "各回の CSV: $RESULTS_DIR/${MODE}-${RUN_DATE}-*-{poll,event}.csv（N=1/10/50/all をそれぞれ POLL/EVENT で計測）"
    if (( CHECK_FAIL_COUNT > 0 )); then
      warn "動作チェックポイントで ${CHECK_FAIL_COUNT} 件の FAIL が記録されています。結果ファイルで詳細を確認してください。"
    else
      say "動作チェックポイント a〜h の8項目はすべて PASS でした。"
    fi
    note "ticks lost (ground truth) は Stage 9 で算出済みです（CountTicks.mq5 + compare_tick_counts.py、POLL 必須・EVENT 任意）。"
    note "結果は $RESULTS_MD の \"N=10 ground truth\" セクションにあります。"

    say "N ごとの POLL/EVENT 比較（詳細な数値は $RESULTS_MD の各セクション、または各 csv を参照してください）:"
    for _pair in "N1:N=1" "N10:N=10" "N50:N=50" "Nall:N=all"; do
      _k="${_pair%%:*}"; _lbl="${_pair##*:}"
      _pv="STATS_${_k}_POLL"; _ev="STATS_${_k}_EVENT"
      if [[ -n "${!_pv:-}" || -n "${!_ev:-}" ]]; then
        note "  ${_lbl}:"
        note "    poll : ${!_pv:-（未計測）}"
        note "    event: ${!_ev:-（未計測）}"
      fi
    done
    say "上のペアそれぞれについて、symbol_scaling.py の表（該当 csv、または実行時の標準出力）から hop p50/p99 を"
    say "読み、値が小さいほうを「勝ち」としてメモしてください。このウィザードは POLL/EVENT の結果を並べるだけで、"
    say "自動判定はしません。チェック 4i の evt_late/evt_n 比が高い N では EVENT の勝ち幅が小さくなる傾向に注意してください。"

    note "baseline-${RUN_DATE}.md と after-${RUN_DATE}.md を突き合わせて docs/latency.md の"
    note "Symbol scaling table を更新してください（同一市場セッション内の計測であることを確認）。"
  fi
fi

finish
